        "Feature Buy-in": "\u0C2B\u0C40\u0C1A\u0C30\u0C4D \u0C2C\u0C48-\u0C07\u0C28\u0C4D",
        "Features Tags": "\u0C2B\u0C40\u0C1A\u0C30\u0C4D\u0C38\u0C4D \u0C1F\u0C4D\u0C2F\u0C3E\u0C17\u0C4D\u200C\u0C32\u0C41",
        Fiat: X,
        "First Deposit Bonus": "\u0C2E\u0C4A\u0C26\u0C1F\u0C3F \u0C21\u0C3F\u0C2A\u0C3E\u0C1C\u0C3F\u0C1F\u0C4D \u0C2C\u0C4B\u0C28\u0C38\u0C4D",
        "For Android Setup": "Android \u0C38\u0C46\u0C1F\u0C2A\u0C4D \u0C15\u0C4B\u0C38\u0C02",
