        "trans.mainpage.coun.format": "<1></1> \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C3E\u0C30\u0C41",
