        "trans.mainpage.footer.desc.new1": "\u0C2E\u0C40\u0C30\u0C41 {{host1}} \u0C28\u0C3F \u0C09\u0C2A\u0C2F\u0C4B\u0C17\u0C3F\u0C02\u0C1A\u0C21\u0C02 \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C2F\u0C3E\u0C15\u0C4D\u0C38\u0C46\u0C38\u0C4D \u0C1A\u0C47\u0C2F\u0C21\u0C02 \u0C05\u0C02\u0C1F\u0C47 \u0C2E\u0C40\u0C30\u0C41 \u0C2E\u0C3E \u0C38\u0C47\u0C35\u0C3E \u0C28\u0C3F\u0C2C\u0C02\u0C27\u0C28\u0C32\u0C41 \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C2C\u0C3E\u0C27\u0C4D\u0C2F\u0C24\u0C3E\u0C2F\u0C41\u0C24\u0C2E\u0C48\u0C28 \u0C17\u0C47\u0C2E\u0C3F\u0C02\u0C17\u0C4D \u0C2A\u0C3E\u0C32\u0C38\u0C40 \u0C2F\u0C4A\u0C15\u0C4D\u0C15 \u0C15\u0C02\u0C1F\u0C46\u0C02\u0C1F\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C2A\u0C42\u0C30\u0C4D\u0C24\u0C3F\u0C17\u0C3E \u0C05\u0C30\u0C4D\u0C25\u0C02 \u0C1A\u0C47\u0C38\u0C41\u0C15\u0C41\u0C28\u0C4D\u0C28\u0C3E\u0C30\u0C28\u0C3F \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C1A\u0C1F\u0C4D\u0C1F\u0C2C\u0C26\u0C4D\u0C27\u0C02\u0C17\u0C3E \u0C15\u0C1F\u0C4D\u0C1F\u0C41\u0C2C\u0C21\u0C3F \u0C09\u0C02\u0C21\u0C1F\u0C3E\u0C28\u0C3F\u0C15\u0C3F \u0C05\u0C02\u0C17\u0C40\u0C15\u0C30\u0C3F\u0C38\u0C4D\u0C24\u0C41\u0C28\u0C4D\u0C28\u0C3E\u0C30\u0C28\u0C3F \u0C38\u0C42\u0C1A\u0C3F\u0C38\u0C4D\u0C24\u0C41\u0C02\u0C26\u0C3F. ",
        "trans.mainpage.footer.desc.new3": "{{siteName}}.\u0C2E\u0C3E\u0C30\u0C4D\u0C2A\u0C3F\u0C21\u0C3F \u0C38\u0C47\u0C35\u0C28\u0C41 \u0C2E\u0C3E \u0C2D\u0C3E\u0C17\u0C38\u0C4D\u0C35\u0C3E\u0C2E\u0C3F <2>Cwallet</2> \u0C05\u0C02\u0C26\u0C3F\u0C38\u0C4D\u0C24\u0C4B\u0C02\u0C26\u0C3F.",
        "trans.mainpage.footer.desc1": "\u0C2C\u0C39\u0C41\u0C33-\u0C05\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C41 \u0C17\u0C46\u0C32\u0C41\u0C1A\u0C41\u0C15\u0C41\u0C28\u0C4D\u0C28 \u0C15\u0C4D\u0C30\u0C3F\u0C2A\u0C4D\u0C1F\u0C4B \u0C15\u0C4D\u0C2F\u0C3E\u0C38\u0C3F\u0C28\u0C4B. \u0C2A\u0C4D\u0C32\u0C47\u0C2F\u0C30\u0C4D-\u0C38\u0C46\u0C02\u0C1F\u0C4D\u0C30\u0C3F\u0C15\u0C4D \u0C35\u0C3F\u0C27\u0C3E\u0C28\u0C02\u0C24\u0C4B, <1>{{host1}}</1> \u0C2A\u0C4D\u0C30\u0C2A\u0C02\u0C1A\u0C35\u0C4D\u0C2F\u0C3E\u0C2A\u0C4D\u0C24\u0C02\u0C17\u0C3E \u0C2E\u0C3F\u0C32\u0C3F\u0C2F\u0C28\u0C4D\u0C32 \u0C2E\u0C02\u0C26\u0C3F \u0C1C\u0C42\u0C26\u0C17\u0C3E\u0C33\u0C4D\u0C32\u0C28\u0C41 \u0C38\u0C02\u0C24\u0C43\u0C2A\u0C4D\u0C24\u0C3F\u0C2A\u0C30\u0C1A\u0C17\u0C32\u0C26\u0C41. <3>{{host2}}</3> \u0C26\u0C3E\u0C28\u0C3F \u0C15\u0C2E\u0C4D\u0C2F\u0C42\u0C28\u0C3F\u0C1F\u0C40\u0C2A\u0C48 \u0C26\u0C3E\u0C28\u0C3F \u0C2A\u0C4D\u0C30\u0C3E\u0C27\u0C3E\u0C28\u0C4D\u0C2F\u0C24\u0C28\u0C41 \u0C38\u0C46\u0C1F\u0C4D \u0C1A\u0C47\u0C38\u0C3F\u0C02\u0C26\u0C3F, \u0C07\u0C26\u0C3F \u0C36\u0C3E\u0C36\u0C4D\u0C35\u0C24\u0C2E\u0C48\u0C28 \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C05\u0C02\u0C24\u0C41\u0C32\u0C47\u0C28\u0C3F \u0C35\u0C3F\u0C28\u0C4B\u0C26\u0C2D\u0C30\u0C3F\u0C24\u0C2E\u0C48\u0C28 \u0C1C\u0C42\u0C26\u0C02 \u0C05\u0C28\u0C41\u0C2D\u0C35\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C28\u0C3F\u0C30\u0C4D\u0C27\u0C3E\u0C30\u0C3F\u0C38\u0C4D\u0C24\u0C41\u0C02\u0C26\u0C3F.",
        "trans.mainpage.free.bonus": "<2>{{amount}}</2> \u0C21\u0C3F\u0C2A\u0C3E\u0C1C\u0C3F\u0C1F\u0C4D \u0C2C\u0C4B\u0C28\u0C38\u0C4D\u200C\u0C28\u0C41 \u0C24\u0C15\u0C4D\u0C37\u0C23\u0C2E\u0C47 \u0C30\u0C40\u0C21\u0C40\u0C2E\u0C4D \u0C1A\u0C47\u0C2F\u0C21\u0C3E\u0C28\u0C3F\u0C15\u0C3F \u0C07\u0C2A\u0C4D\u0C2A\u0C41\u0C21\u0C47 <0>\u0C28\u0C2E\u0C4B\u0C26\u0C41 \u0C1A\u0C47\u0C38\u0C41\u0C15\u0C4B\u0C02\u0C21\u0C3F</0>!",
        "trans.mainpage.free.bonus.unlock": "{{host}} \u0C35\u0C26\u0C4D\u0C26 \u0C2A\u0C4D\u0C30\u0C24\u0C4D\u0C2F\u0C47\u0C15\u0C2E\u0C48\u0C28 <1>VIP</1> \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C05\u0C28\u0C4D\u200C\u0C32\u0C3E\u0C15\u0C4D \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F!",
        "trans.mainpage.live.stats": "\u0C1A\u0C47\u0C30\u0C41\u0C15\u0C4B\u0C35\u0C21\u0C3E\u0C28\u0C3F\u0C15\u0C3F <1></1> \u0C2E\u0C30\u0C3F\u0C02\u0C24 {{wagerCurrency}} \u0C2A\u0C02\u0C26\u0C46\u0C02 \u0C35\u0C47\u0C2F\u0C02\u0C21\u0C3F",
        "trans.mainpage.log.wager": "\u0C32\u0C3E\u0C17\u0C3F\u0C28\u0C4D \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C2A\u0C02\u0C26\u0C46\u0C02 <1>{{amount}}</1> \u0C30\u0C4B\u0C1C\u0C41\u0C35\u0C3E\u0C30\u0C40",
        "trans.mainpage.next.bonus": "\u0C24\u0C26\u0C41\u0C2A\u0C30\u0C3F \u0C38\u0C4D\u0C25\u0C3E\u0C2F\u0C3F \u0C2C\u0C4B\u0C28\u0C38\u0C4D <1>{{amount_info}}</1>",
        "trans.mainpage.prize.pool": "<4>{{typeName}}</4> \u0C2A\u0C4B\u0C1F\u0C40 \u0C2A\u0C4D\u0C30\u0C48\u0C1C\u0C4D \u0C2A\u0C42\u0C32\u0C4D\u200C\u0C32\u0C4B <0>{{number1}}</0> \u0C38\u0C4D\u0C25\u0C3E\u0C28\u0C02 \u2013 <2>{{number2}}</2>",
        "trans.mainpage.raffle.desc1": "\u0C2E\u0C40 \u0C30\u0C4B\u0C1C\u0C41\u0C35\u0C3E\u0C30\u0C40 \u0C30\u0C3E\u0C2B\u0C3F\u0C32\u0C4D \u0C1F\u0C3F\u0C15\u0C4D\u0C15\u0C46\u0C1F\u0C4D\u200C\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C21\u0C3E\u0C28\u0C3F\u0C15\u0C3F <1>{{wager_amount}}</1> \u0C2A\u0C02\u0C26\u0C46\u0C02 \u0C35\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
        "trans.mainpage.raffle.desc2": "\u0C2E\u0C30\u0C4B \u0C05\u0C26\u0C28\u0C2A\u0C41 \u0C30\u0C3E\u0C2B\u0C3F\u0C32\u0C4D \u0C1F\u0C3F\u0C15\u0C4D\u0C15\u0C46\u0C1F\u0C4D\u200C\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C21\u0C3E\u0C28\u0C3F\u0C15\u0C3F <1>{{wager_amount}}</1> \u0C2A\u0C02\u0C26\u0C46\u0C02 \u0C35\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
        "trans.mainpage.raffle.desc3": "<1>{{ticket_count}}</1> \u0C1F\u0C3F\u0C15\u0C4D\u0C15\u0C46\u0C1F\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C3E\u0C30\u0C41",
        "trans.mainpage.refer.add": '<0>{{host}}</0> \u0C15\u0C2E\u0C40\u0C37\u0C28\u0C4D\u200C\u0C24\u0C4B \u0C2A\u0C3E\u0C1F\u0C41 \u0C2E\u0C40\u0C30\u0C41 \u0C06\u0C39\u0C4D\u0C35\u0C3E\u0C28\u0C3F\u0C02\u0C1A\u0C47 \u0C2A\u0C4D\u0C30\u0C24\u0C3F \u0C30\u0C46\u0C2B\u0C30\u0C32\u0C4D\u200C\u0C15\u0C41 {{amount}} \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D\u200C\u0C28\u0C41 \u0C38\u0C46\u0C1F\u0C2A\u0C4D \u0C1A\u0C47\u0C38\u0C4D\u0C24\u0C41\u0C02\u0C26\u0C3F. \u0C07\u0C2A\u0C4D\u0C2A\u0C41\u0C21\u0C47 "\u0C15\u0C3E\u0C2A\u0C40 \u0C32\u0C3F\u0C02\u0C15\u0C4D"\u0C28\u0C3F \u0C15\u0C4D\u0C32\u0C3F\u0C15\u0C4D \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F, \u0C26\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C2E\u0C40 \u0C38\u0C4D\u0C28\u0C47\u0C39\u0C3F\u0C24\u0C41\u0C32\u0C15\u0C41 \u0C2A\u0C02\u0C2A\u0C02\u0C21\u0C3F \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C2E\u0C40 \u0C38\u0C02\u0C2A\u0C26 \u0C2A\u0C4D\u0C30\u0C2F\u0C3E\u0C23\u0C02\u0C32\u0C4B \u0C35\u0C46\u0C02\u0C1F\u0C28\u0C47 \u0C15\u0C4A\u0C24\u0C4D\u0C24 \u0C05\u0C27\u0C4D\u0C2F\u0C3E\u0C2F\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C2A\u0C4D\u0C30\u0C3E\u0C30\u0C02\u0C2D\u0C3F\u0C02\u0C1A\u0C02\u0C21\u0C3F!',
        "trans.mainpage.refer.desc": "\u0C38\u0C4D\u0C28\u0C47\u0C39\u0C3F\u0C24\u0C41\u0C21\u0C3F\u0C28\u0C3F \u0C38\u0C3F\u0C2B\u0C3E\u0C30\u0C4D\u0C38\u0C41 \u0C1A\u0C47\u0C38\u0C3F, <1><br/>{{number}}</1> <3>+</3> <5>15%<br/></5> \u0C15\u0C2E\u0C40\u0C37\u0C28\u0C4D \u0C2A\u0C4A\u0C02\u0C26\u0C02\u0C21\u0C3F",
        "trans.mainpage.referral.desc1": "\u0C2E\u0C40 <1>{{localAmountStr}}</1> \u0C30\u0C46\u0C2B\u0C30\u0C32\u0C4D \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C02\u0C21\u0C3F",
        "trans.mainpage.referral.desc2": "\u0C2E\u0C40\u0C30\u0C41 \u0C06\u0C39\u0C4D\u0C35\u0C3E\u0C28\u0C3F\u0C02\u0C1A\u0C3F\u0C28 \u0C2A\u0C4D\u0C30\u0C24\u0C3F \u0C38\u0C4D\u0C28\u0C47\u0C39\u0C3F\u0C24\u0C41\u0C21\u0C41, \u0C2E\u0C40\u0C15\u0C41 {{localAmountStr}} \u0C28\u0C3F \u0C05\u0C02\u0C26\u0C41\u0C15\u0C41\u0C02\u0C1F\u0C3E\u0C30\u0C41, \u0C2E\u0C40\u0C30\u0C41 \u0C0E\u0C02\u0C24 \u0C0E\u0C15\u0C4D\u0C15\u0C41\u0C35 \u0C06\u0C39\u0C4D\u0C35\u0C3E\u0C28\u0C3F\u0C38\u0C4D\u0C24\u0C47 \u0C05\u0C02\u0C24 \u0C0E\u0C15\u0C4D\u0C15\u0C41\u0C35 \u0C2A\u0C4A\u0C02\u0C26\u0C41\u0C24\u0C3E\u0C30\u0C41!",
        "trans.mainpage.referral.desc3": "\u0C2E\u0C40 <1>25%</1> \u0C15\u0C2E\u0C40\u0C37\u0C28\u0C4D \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D\u200C\u0C32\u0C28\u0C41 \u0C2A\u0C4A\u0C02\u0C26\u0C02\u0C21\u0C3F",
        "trans.mainpage.signup.bonus": "\u0C38\u0C48\u0C28\u0C4D \u0C05\u0C2A\u0C4D \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F \u0C2E\u0C30\u0C3F\u0C2F\u0C41 <1>\u0C2A\u0C4A\u0C02\u0C26\u0C02\u0C21\u0C3F</1> \u0C30\u0C3F\u0C35\u0C3E\u0C30\u0C4D\u0C21\u0C4D <br/> \u0C35\u0C30\u0C15\u0C41",
